16	func init() {
17		if env := os.Getenv("E2E_AGENT"); env != "" && env != "vogon" {
18			return
19		}
20		// Only register if the binary exists (built by the test runner).
21		if _, err := exec.LookPath("vogon"); err != nil {
22			return
23		}
24		Register(&Vogon{})
