27	// Vogon implements the Agent interface using a deterministic binary
28	// that creates files and fires hooks without making any API calls.
29	// Named after the Vogons from The Hitchhiker's Guide to the Galaxy.
30	type Vogon struct{}
31	
32	func (v *Vogon) Name() string               { return "vogon" }
33	func (v *Vogon) Binary() string             { return "vogon" }
34	func (v *Vogon) EntireAgent() string        { return "vogon" }
35	func (v *Vogon) PromptPattern() string      { return `>` }
36	func (v *Vogon) TimeoutMultiplier() float64 { return 0.5 } // Faster than real agents
37	
38	func (v *Vogon) Bootstrap() error { return nil }
39	
40	func (v *Vogon) IsTransientError(_ Output, _ error) bool { return false }
41	
42	func (v *Vogon) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
43		args := []string{"-p", prompt}
44		displayArgs := []string{"-p", fmt.Sprintf("%q", prompt)}
45	
46		cmd := exec.CommandContext(ctx, v.Binary(), args...)
47		cmd.Dir = dir
48		cmd.Stdin = nil
49		cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
50		cmd.Env = append(cmd.Env, "HOME="+vogonHomeDir(dir))
51		setupProcessGroup(cmd)
52		cmd.WaitDelay = 5 * time.Second
53	
54		var stdout, stderr strings.Builder
55		cmd.Stdout = &stdout
56		cmd.Stderr = &stderr
57	
58		err := cmd.Run()
59		exitCode := 0
60		if err != nil {
61			exitErr := &exec.ExitError{}
62			if errors.As(err, &exitErr) {
63				exitCode = exitErr.ExitCode()
64			} else {
65				exitCode = -1
66			}
67		}
68	
69		return Output{
70			Command:  v.Binary() + " " + strings.Join(displayArgs, " "),
71			Stdout:   stdout.String(),
72			Stderr:   stderr.String(),
73			ExitCode: exitCode,
74		}, err
75	}
76	
77	func (v *Vogon) StartSession(_ context.Context, dir string) (Session, error) {
78		name := fmt.Sprintf("vogon-test-%d", time.Now().UnixNano())
79		s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY", "HOME=" + vogonHomeDir(dir)}, v.Binary())
80		if err != nil {
81			return nil, err
82		}
83	
84		// Wait for the interactive prompt.
85		if _, err := s.WaitFor(`>`, 10*time.Second); err != nil {
86			_ = s.Close()
87			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
88		}
89		s.stableAtSend = ""
90	
91		return s, nil
92	}
