94	// WriteSessionTranscript creates a deterministic vogon session transcript
95	// without firing hooks or mutating the repository. Attach E2E tests use this
96	// to prepare a session that `entire attach` can import.
97	func (v *Vogon) WriteSessionTranscript(ctx context.Context, dir string, extraEnv []string, sessionID, userPrompt, assistantMessage string) (Output, error) {
98		args := []string{
99			"--write-session",
100			"--session-id", sessionID,
101			"--user-prompt", userPrompt,
102			"--assistant-message", assistantMessage,
103		}
104		displayArgs := []string{
105			"--write-session",
106			"--session-id", sessionID,
107			"--user-prompt", fmt.Sprintf("%q", userPrompt),
108			"--assistant-message", fmt.Sprintf("%q", assistantMessage),
109		}
110	
111		cmd := exec.CommandContext(ctx, v.Binary(), args...)
112		cmd.Dir = dir
113		cmd.Stdin = nil
114		cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
115		cmd.Env = append(cmd.Env, extraEnv...)
116		if !hasEnvVar(extraEnv, "HOME") {
117			cmd.Env = append(cmd.Env, "HOME="+vogonHomeDir(dir))
118		}
119		setupProcessGroup(cmd)
120		cmd.WaitDelay = 5 * time.Second
121	
122		var stdout, stderr strings.Builder
123		cmd.Stdout = &stdout
124		cmd.Stderr = &stderr
125	
126		err := cmd.Run()
127		exitCode := 0
128		if err != nil {
129			exitErr := &exec.ExitError{}
130			if errors.As(err, &exitErr) {
131				exitCode = exitErr.ExitCode()
132			} else {
133				exitCode = -1
134			}
135		}
136	
137		return Output{
138			Command:  v.Binary() + " " + strings.Join(displayArgs, " "),
139			Stdout:   stdout.String(),
140			Stderr:   stderr.String(),
141			ExitCode: exitCode,
142		}, err
143	}
