145	func vogonHomeDir(dir string) string {
146		sum := sha256.Sum256([]byte(dir))
147		homeDir := filepath.Join(os.TempDir(), "vogon-e2e-home-"+hex.EncodeToString(sum[:6]))
148		if err := os.MkdirAll(homeDir, 0o755); err != nil {
149			panic(fmt.Sprintf("create vogon home %s: %v", homeDir, err))
150		}
151		return homeDir
152	}
153	
154	func hasEnvVar(env []string, key string) bool {
155		for _, entry := range env {
156			if strings.HasPrefix(entry, key+"=") {
157				return true
158			}
159		}
160		return false
161	}
